/**
 * StudentForm.jsx
 *
 * Used for both creating and editing student records.
 *
 * KEY CHANGES for Phase 6 (backend integration):
 *
 * 1. The Student ID is now auto-generated by MySQL (auto-increment Long).
 *    - On CREATE: we do NOT show or send an ID field. The backend assigns it.
 *    - On EDIT: we display the ID as read-only text (informational only).
 *
 * 2. The year field is a string label in the UI ("First Year", "Second Year", etc.)
 *    but the backend expects an integer (1, 2, 3, 4).
 *    The studentService.js handles this conversion transparently.
 *
 * 3. addStudent() and updateStudent() from StudentContext are now async.
 *    The form awaits them and shows errors inline if the backend rejects the request.
 *
 * 4. After success, the user is navigated to the student's profile using the
 *    backend-assigned numeric ID (e.g., /students/3).
 */

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { BRANCH_OPTIONS, YEAR_OPTIONS } from '../../data/mockStudents.js';
import { validateStudentFormForBackend } from '../../utils/validation.js';
import { FormInput } from '../common/FormInput.jsx';
import { Button } from '../common/Button.jsx';
import { useStudents } from '../../context/StudentContext.jsx';
import { AlertCircle } from 'lucide-react';

export const StudentForm = ({
  initialData = null,
  isEdit = false,
  onSubmitSuccess
}) => {
  const navigate = useNavigate();
  const { addStudent, updateStudent } = useStudents();

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    branch: 'Computer Engineering',
    year: 'First Year'
  });

  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Populate form fields when editing an existing student
  useEffect(() => {
    if (initialData) {
      setFormData({
        name: initialData.name || '',
        email: initialData.email || '',
        branch: initialData.branch || 'Computer Engineering',
        year: initialData.year || 'First Year'
      });
    }
  }, [initialData]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: null }));
    }
    if (apiError) setApiError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Client-side validation (no backend call yet)
    const validation = validateStudentFormForBackend(formData);
    if (!validation.isValid) {
      setErrors(validation.errors);
      return;
    }

    setIsSubmitting(true);
    setApiError('');

    try {
      if (isEdit) {
        // updateStudent(id, data) — id is the DB numeric id from initialData
        const updated = await updateStudent(initialData.id, formData);
        if (onSubmitSuccess) {
          onSubmitSuccess(updated.id);
        } else {
          navigate(`/students/${updated.id}`);
        }
      } else {
        // addStudent(data) — backend assigns the ID
        const created = await addStudent(formData);
        if (onSubmitSuccess) {
          onSubmitSuccess(created.id);
        } else {
          navigate('/students');
        }
      }
    } catch (err) {
      // Show server-side errors (e.g., duplicate email, validation failure)
      setApiError(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleCancel = () => {
    if (isEdit && initialData?.id) {
      navigate(`/students/${initialData.id}`);
    } else {
      navigate('/students');
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6 max-w-2xl bg-white border border-[#EAEAEA] rounded p-6 sm:p-8">

      {/* API / server error banner */}
      {apiError && (
        <div
          role="alert"
          className="p-3 bg-[#FFF5F5] border border-red-200 rounded flex items-start gap-2.5 text-xs text-red-700"
        >
          <AlertCircle className="w-4 h-4 shrink-0 mt-0.5 text-red-500" />
          <span>{apiError}</span>
        </div>
      )}

      <div className="space-y-4">
        {/* Show read-only ID when editing, hidden on create (backend assigns it) */}
        {isEdit && initialData?.id && (
          <div className="space-y-1">
            <label className="block text-xs font-semibold text-[#404040] uppercase tracking-wide font-heading">
              Student ID
            </label>
            <p className="font-mono text-sm font-semibold text-black bg-[#F5F5F5] border border-[#EAEAEA] rounded px-3 py-2">
              {initialData.id}
            </p>
            <p className="text-xs text-[#737373]">
              Database-assigned ID — cannot be changed.
            </p>
          </div>
        )}

        {/* Full Name */}
        <FormInput
          id="student-name"
          name="name"
          label="Full Name"
          placeholder="e.g. Aarav Sharma"
          value={formData.name}
          onChange={handleChange}
          error={errors.name}
          required
          disabled={isSubmitting}
        />

        {/* Email */}
        <FormInput
          id="student-email"
          name="email"
          type="email"
          label="College Email"
          placeholder="e.g. student@college.edu"
          value={formData.email}
          onChange={handleChange}
          error={errors.email}
          required
          disabled={isSubmitting}
        />

        {/* Branch Selection */}
        <FormInput
          id="student-branch"
          name="branch"
          type="select"
          label="Branch / Engineering Discipline"
          value={formData.branch}
          onChange={handleChange}
          error={errors.branch}
          options={BRANCH_OPTIONS}
          required
          disabled={isSubmitting}
        />

        {/* Academic Year */}
        <FormInput
          id="student-year"
          name="year"
          type="select"
          label="Academic Year"
          value={formData.year}
          onChange={handleChange}
          error={errors.year}
          options={YEAR_OPTIONS}
          required
          disabled={isSubmitting}
        />
      </div>

      {/* Form Action Buttons */}
      <div className="pt-4 border-t border-[#EAEAEA] flex items-center justify-end gap-3">
        <Button
          type="button"
          variant="secondary"
          onClick={handleCancel}
          disabled={isSubmitting}
        >
          Cancel
        </Button>
        <Button
          type="submit"
          variant="primary"
          disabled={isSubmitting}
        >
          {isSubmitting
            ? (isEdit ? 'Saving…' : 'Adding…')
            : (isEdit ? 'Save Changes' : 'Save Student')
          }
        </Button>
      </div>
    </form>
  );
};
